package cn.nebulaedata.cccs.nebuwork.backend.api.agent;

import cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException;
import cn.nebulaedata.cccs.nebuwork.backend.api.workbench.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;
import java.io.IOException;
import java.util.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.BusinessValues.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiSupport.map;

@Service
public class AgentTasks {
    private final AgentStore db;private final AgentClient engine;private final WorkbenchMapper projects;private final ObjectMapper json;private final AgentUsage usage;
    public AgentTasks(AgentStore db,AgentClient engine,WorkbenchMapper projects,ObjectMapper json,AgentUsage usage){this.db=db;this.engine=engine;this.projects=projects;this.json=json;this.usage=usage;}
    public Map<String,Object> project(String owner,String id,boolean write){Map<String,Object> p=projects.project(owner,id);if(p==null)throw new ApiException(404,"项目不存在");if(write&&!"active".equals(p.get("status")))throw new ApiException(409,"请先恢复项目再执行任务");return p;}
    public Map<String,Object> owned(String owner,String task){Map<String,Object> t=db.task(task);if(t==null||!owner.equals(t.get("owner_id"))||t.get("deleted_at")!=null)throw new ApiException(404,"任务不存在");project(owner,str(t,"project_id"),false);return t;}
    private Map<String,Object> view(Map<String,Object> task,JsonNode session){return map("id",task.get("id"),"projectId",task.get("project_id"),"sessionId",task.get("session_id"),"title",task.get("title"),"context",decode(json,task.get("context_json")),"status",session.path("status").asText("idle"),"createdAt",time(task.get("created_at")),"updatedAt",session.path("updatedAt").asText(Objects.toString(time(task.get("updated_at")),"")));}
    public List<Object> list(String owner,String project){project(owner,project,false);Map<String,JsonNode> sessions=new HashMap<>();for(JsonNode s:engine.get(owner,project,"/v1/projects/"+AgentClient.segment(project)+"/sessions").path("items"))sessions.put(s.path("id").asText(),s);List<Object> result=new ArrayList<>();for(Map<String,Object> row:db.rows("SELECT * FROM nw_agent_task WHERE owner_id=? AND project_id=? AND deleted_at IS NULL ORDER BY updated_at DESC",owner,project))result.add(view(row,sessions.getOrDefault(str(row,"session_id"),json.createObjectNode())));JsonNode data=usage.load(owner,project);Map<String,Map<String,Object>> measured=new HashMap<>();for(Map<String,Object> t:usage.tasks(owner,data,project))measured.put(str(t,"id"),t);for(Object item:result){Map<String,Object> t=(Map<String,Object>)item;Map<String,Object> fact=measured.get(str(t,"id"));t.put("usage",fact==null?usage.unavailable():fact.get("usage"));}return result;}
    @Transactional public Object create(String owner,String project,JsonNode body,String requestKey){
        project(owner,project,true);key(requestKey);String title=text(body,"title",240,false);if(title.isEmpty()){String content=text(body,"content",100000,true);title=content.substring(0,Math.min(80,content.length()));}
        JsonNode context=body.path("context").isObject()?body.path("context"):json.createObjectNode();String digest=fingerprint(body),id="task-"+hash(owner+":"+project+":"+requestKey).substring(0,40);
        db.update("INSERT INTO nw_agent_task(id,owner_id,project_id,title,context_json,request_key,request_hash) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id",id,owner,project,title,context.toString(),requestKey,digest);
        Map<String,Object> task=db.one("SELECT * FROM nw_agent_task WHERE id=? FOR UPDATE",id);if(!digest.equals(task.get("request_hash")))throw new ApiException(409,"同一请求编号不能创建不同任务");
        if(task.get("session_id")==null){JsonNode session=engine.post(owner,project,"/v1/sessions",map("projectId",project,"taskId",id,"title",title),"session:"+id);db.update("UPDATE nw_agent_task SET session_id=? WHERE id=?",session.path("id").asText(),id);}
        if(!body.path("content").asText("").trim().isEmpty())send(owner,id,body,"initial:"+id);
        return detail(owner,id);
    }
    public Object detail(String owner,String taskId){Map<String,Object> task=owned(owner,taskId);JsonNode remote=engine.get(owner,str(task,"project_id"),"/v1/sessions/"+AgentClient.segment(str(task,"session_id")));ObjectNode result=remote.deepCopy();Map<String,Object> taskView=view(task,remote.path("session"));taskView.put("usage",remote.path("usage"));result.set("task",json.valueToTree(taskView));return result;}
    public JsonNode runs(String owner,String task){Map<String,Object> t=owned(owner,task);return engine.get(owner,str(t,"project_id"),"/v1/sessions/"+AgentClient.segment(str(t,"session_id"))+"/runs");}
    public JsonNode send(String owner,String taskId,JsonNode body,String requestKey){Map<String,Object> task=owned(owner,taskId);String project=str(task,"project_id");project(owner,project,true);ObjectNode input=json.createObjectNode().put("content",text(body,"content",100000,true));input.set("fileIds",body.path("fileIds").isArray()?body.path("fileIds"):json.createArrayNode());if(body.has("fileRefs"))input.set("fileRefs",body.path("fileRefs"));if(body.has("context"))input.set("context",body.path("context"));if(body.has("retryOf"))input.set("retryOf",body.path("retryOf"));JsonNode result=engine.post(owner,project,"/v1/sessions/"+AgentClient.segment(str(task,"session_id"))+"/runs",input,requestKey);db.update("UPDATE nw_agent_task SET updated_at=CURRENT_TIMESTAMP(6) WHERE id=?",taskId);return result;}
    public JsonNode run(String owner,String taskId,String runId){Map<String,Object> task=owned(owner,taskId);JsonNode run=engine.get(owner,str(task,"project_id"),"/v1/runs/"+AgentClient.segment(runId));if(!str(task,"session_id").equals(run.path("sessionId").asText())){String parent=run.path("parentRunId").asText("");if(parent.isEmpty())throw new ApiException(404,"执行不属于该任务");JsonNode root=engine.get(owner,str(task,"project_id"),"/v1/runs/"+AgentClient.segment(parent));if(!str(task,"session_id").equals(root.path("sessionId").asText()))throw new ApiException(404,"执行不属于该任务");}return run;}
    public JsonNode command(String owner,String task,String run,JsonNode body,String requestKey){Map<String,Object> t=owned(owner,task);run(owner,task,run);return engine.post(owner,str(t,"project_id"),"/v1/runs/"+AgentClient.segment(run)+"/commands",body,requestKey);}
    public JsonNode events(String owner,String task,long after){Map<String,Object> t=owned(owner,task);return engine.get(owner,str(t,"project_id"),"/v1/sessions/"+AgentClient.segment(str(t,"session_id"))+"/events?format=json&after="+Math.max(0,after));}
    public JsonNode expert(String owner,String task,String run){Map<String,Object> t=owned(owner,task);JsonNode invocation=run(owner,task,run);return engine.get(owner,str(t,"project_id"),"/v1/sessions/"+AgentClient.segment(invocation.path("sessionId").asText()));}
    public Object edit(String owner,String task,JsonNode body){owned(owner,task);String title=text(body,"title",240,true);db.update("UPDATE nw_agent_task SET title=?,context_json=?,updated_at=CURRENT_TIMESTAMP(6) WHERE id=? AND owner_id=?",title,body.path("context").isObject()?body.path("context").toString():"{}",task,owner);return detail(owner,task);}
    public JsonNode artifacts(String owner,String project){project(owner,project,false);return engine.get(owner,project,"/v1/projects/"+AgentClient.segment(project)+"/artifacts");}
    public JsonNode upload(String owner,String project,String taskId,MultipartFile file,String requestKey)throws IOException{project(owner,project,true);if(file.getSize()>20*1024*1024)throw new ApiException(413,"单个附件不能超过 20 MiB");ObjectNode body=json.createObjectNode().put("name",Objects.toString(file.getOriginalFilename(),"file")).put("mediaType",Objects.toString(file.getContentType(),"application/octet-stream")).put("contentBase64",Base64.getEncoder().encodeToString(file.getBytes()));if(taskId!=null&&!taskId.isEmpty()){Map<String,Object> task=owned(owner,taskId);if(!project.equals(task.get("project_id")))throw new ApiException(404,"任务不属于该项目");body.put("sessionId",str(task,"session_id"));}return engine.post(owner,project,"/v1/projects/"+AgentClient.segment(project)+"/artifacts",body,requestKey);}
    public Object grant(String owner,String sourceTask,String targetTask,long before,String requestKey){Map<String,Object> source=owned(owner,sourceTask),target=owned(owner,targetTask);return engine.post(owner,null,"/v1/session-grants",map("sourceSessionId",source.get("session_id"),"targetSessionId",target.get("session_id"),"beforeSequence",before),requestKey);}
    public Map<String,Object> workbenchUsage(String owner,String workbench){Map<String,Object> row=map("id",workbench);usage.workbenches(owner,Collections.singletonList(row));return (Map<String,Object>)row.get("taskStats");}
    public boolean hasActive(String owner,String project){for(Object item:list(owner,project)){String status=Objects.toString(((Map<?,?>)item).get("status"),"idle");if(!"idle".equals(status)&&!TERMINAL.contains(status))return true;}return false;}
    public void enrichProject(String owner,Map<String,Object> project){usage.projects(owner,Collections.singletonList(project));project.put("capabilities",map("execution",true,"resources",true));}
}
